///A point.
class Point {

    ///The label.
    final String? label;
    final double x;
    final double y;

    Point({
        this.label,
        required this.x,
        required this.y,
    });

    factory Point.fromJson(Map<String, dynamic> json) => Point(
        label: json["label"],
        x: json["x"]?.toDouble(),
        y: json["y"]?.toDouble(),
    );

    Map<String, dynamic> toJson() => {
        "label": label,
        "x": x,
        "y": y,
    };
}

