///The kind.
enum Kind {
    FIRST_KIND,
    SECOND,
    THIRD_KIND,
    DOLLAR,
    WITH_QUOTE
}

final kindValues = EnumValues({
    "first-kind": Kind.FIRST_KIND,
    "SECOND": Kind.SECOND,
    "third_kind": Kind.THIRD_KIND,
    "\u0024dollar": Kind.DOLLAR,
    "with \"quote\"": Kind.WITH_QUOTE
});


///On or off.
enum Status {
    ON,
    OFF
}

final statusValues = EnumValues({
    "on": Status.ON,
    "off": Status.OFF
});

class EnumValues<T> {
    Map<String, T> map;
    late Map<T, String> reverseMap;

    EnumValues(this.map);

    Map<T, String> get reverse {
            reverseMap = map.map((k, v) => MapEntry(v, k));
            return reverseMap;
    }
}

