import 'dart:convert';

TopLevel topLevelFromJson(String str) => TopLevel.fromMap(json.decode(str));

String topLevelToJson(TopLevel data) => json.encode(data.toMap());

List<DateTime> labelsFromJson(String str) => List<DateTime>.from(json.decode(str).map((x) => DateTime.parse(x)));

String labelsToJson(List<DateTime> data) => json.encode(List<dynamic>.from(data.map((x) => x.toIso8601String())));

Map<String, int?> countsFromJson(String str) => Map.from(json.decode(str)).map((k, v) => MapEntry<String, int?>(k, v));

String countsToJson(Map<String, int?> data) => json.encode(Map.from(data).map((k, v) => MapEntry<String, dynamic>(k, v)));

Status statusFromJson(String str) => statusValues.map[json.decode(str)]!;

String statusToJson(Status data) => json.encode(statusValues.reverse[data]);

DateTime? maybeFromJson(String str) => json.decode(str) == null ? null : DateTime.parse(json.decode(str));

String maybeToJson(DateTime? data) => json.encode(data == null ? null : "${data!.year.toString().padLeft(4, '0')}-${data!.month.toString().padLeft(2, '0')}-${data!.day.toString().padLeft(2, '0')}");


