        tags: (() { final x = List<String>.from(json["tags"].map((x) => x)); if (x.length < 1 || x.length > 10) throw FormatException('Invalid array length'); return x; })(),
        withQuoteAnd: json["with \"quote\" and \\"],
    );

    Map<String, dynamic> toJson() => {
        "active": active,
        "anything": anything,
        "byName": Map.from(byName).map((k, v) => MapEntry<String, dynamic>(k, v.toJson())),
        "code": code,
        "copyWith": copyWith,
        "count": count,
        "counts": Map.from(counts).map((k, v) => MapEntry<String, dynamic>(k, v)),
        "created": created.toIso8601String(),
        "dates": dates == null ? null : Map.from(dates!).map((k, v) => MapEntry<String, dynamic>(k, "${v.year.toString().padLeft(4, '0')}-${v.month.toString().padLeft(2, '0')}-${v.day.toString().padLeft(2, '0')}")),
        "day": "${day.year.toString().padLeft(4, '0')}-${day.month.toString().padLeft(2, '0')}-${day.day.toString().padLeft(2, '0')}",
        "empty": empty?.toJson(),
        "hashCode": topLevelHashCode,
        "id": id,
        "kind": kindValues.reverse[kind],
        "kinds": kinds == null ? null : List<dynamic>.from(kinds!.map((x) => kindValues.reverse[x])),
        "maybeByName": maybeByName == null ? null : Map.from(maybeByName!).map((k, v) => MapEntry<String, dynamic>(k, v.toIso8601String())),
        "maybeCode": maybeCode,
        "maybeCount": maybeCount,
        "maybeCreated": maybeCreated?.toIso8601String(),
        "maybeDay": maybeDay == null ? null : "${maybeDay!.year.toString().padLeft(4, '0')}-${maybeDay!.month.toString().padLeft(2, '0')}-${maybeDay!.day.toString().padLeft(2, '0')}",
        "maybeId": maybeId,
        "maybeKind": kindValues.reverse[maybeKind],
        "maybePoint": maybePoint?.toJson(),
        "maybePoints": maybePoints == null ? null : List<dynamic>.from(maybePoints!.map((x) => x?.toJson())),
        "maybeRatio": maybeRatio,
        "maybeTags": maybeTags == null ? null : List<dynamic>.from(maybeTags!.map((x) => x)),
        "mixed": mixed,
        "nested": nested == null ? null : List<dynamic>.from(nested!.map((x) => List<dynamic>.from(x.map((x) => "${x.year.toString().padLeft(4, '0')}-${x.month.toString().padLeft(2, '0')}-${x.day.toString().padLeft(2, '0')}")))),
        "nothing": nothing,
        "optionalDay": optionalDay == null ? null : "${optionalDay!.year.toString().padLeft(4, '0')}-${optionalDay!.month.toString().padLeft(2, '0')}-${optionalDay!.day.toString().padLeft(2, '0')}",
        "optionalPoint": optionalPoint?.toJson(),
        "points": List<dynamic>.from(points.map((x) => x.toJson())),
        "price\u0024": price,
        "ratio": ratio,
        "tags": List<dynamic>.from(tags.map((x) => x)),
        "with \"quote\" and \\": withQuoteAnd,
    };
}


